--- a/src/gpu/GrGpuResourceCacheAccess.h
+++ b/src/gpu/GrGpuResourceCacheAccess.h
@@ -40,6 +40,10 @@
      * Called by the cache to delete the resource under normal circumstances.
      */
     void release() {
+        // Hold a temporary ref across GrGpuResource::release(). release() can run backend-specific
+        // teardown that may drop the last external ref; without this guard, fResource may be
+        // destroyed before the post-release hasRef()/hasNoCommandBufferUsages() check below.
+        sk_sp<GrGpuResource> keepAlive(fResource);
         fResource->release();
         if (!fResource->hasRef() && fResource->hasNoCommandBufferUsages()) {
             delete fResource;

args:
@@ -40,9 +40,12 @@ class GrGpuResource::CacheAccess {
      * Called by the cache to delete the resource under normal circumstances.
      */
     void release() {
+        // Hold a temporary ref across GrGpuResource::release(). release() can run backend-specific
+        // teardown that may drop the last external ref; without this guard, fResource may be
+        // destroyed before the post-release hasRef()/hasNoCommandBufferUsages() check below.
+        sk_sp<GrGpuResource> keepAlive(fResource);
         fResource->release();
         if (!fResource->hasRef() && fResource->hasNoCommandBufferUsages()) {
             delete fResource;
         }
     }
